import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>BMP 是 Windows 上最古老的图片格式，也是最浪费的格式。一张 BMP 截图可能有 20MB，同样图片存成 JPG 只有 500KB，肉眼看不出区别。</p>\n<p>把 BMP 转成 JPG，是让老 Windows 图片重新好用的最快办法。文件缩小 90% 以上，转出来的结果到处都能打开。</p>\n<p>这篇指南会讲清楚 BMP 文件为什么这么大、转换是怎么进行的，以及 JPG 什么时候是正确的目标格式。</p>\n<h2 id=\"what-is-bmp\">什么是 BMP？</h2>\n<p>BMP 是位图（bitmap）的缩写，Windows 的原生图片格式，起源于 1990 年代。它原样保存每个像素，几乎不做压缩。</p>\n<p>这个格式是为处理器很慢、存储很简单的年代设计的。像素直接存放读取很快，那时没人担心文件大小。</p>\n<p>BMP 文件来自老 Windows 软件、扫描仪和存成这个格式的数码相机。老程序的截图也常常是 BMP。</p>\n<p>这个格式支持几种颜色深度，从 1 位黑白到 24 位全彩都有。老文件可能用 8 位调色板，新一点的文件通常是 24 位。</p>\n<h2 id=\"why-bmp-is-huge\">BMP 文件为什么这么大？</h2>\n<p>BMP 保存像素几乎不压缩。一张 1920×1080 的截图用 24 位颜色，光像素就要 6MB 多，还要加上文件头，没有任何办法缩小。</p>\n<p>JPG 把同一张截图压到 500KB，靠的是丢掉人眼几乎注意不到的细节。差别在压缩方式，不在图片本身。</p>\n<p>纯色区域在 BMP 里最浪费空间。JPG 几个字节就能存下的白色背景，BMP 需要几千个字节，因为每个白色像素都要单独存放。</p>\n<p>噪点也很占空间。带纸纹的扫描图有无穷无尽的细微变化，BMP 把每一点都原样保存，JPG 却把它们简化掉了。</p>\n<h2 id=\"how-conversion-works\">BMP 转 JPG 是怎么进行的？</h2>\n<p>转换器直接在浏览器里读取 BMP 文件。BMP 解码是浏览器内置的，不用额外解码器，文件马上就能加载。</p>\n<p>像素画到画布上，再按你选的画质编码成 JPG。图片保持尺寸，看起来一样，文件却大幅缩小。</p>\n<p>单个文件最大支持 25MB，大截图和高清扫描件都不用提前处理，直接就能转。</p>\n<p>转换完全在你的设备上进行。你的扫描件和截图永远不会离开电脑，私人文件和工作文件也不用担心外泄。</p>\n<h2 id=\"quality-settings\">实用的画质设置</h2>\n<p>扫描的文档用 85% 到 90% 画质，文字保持可读，文件大幅缩小。小字在低画质下会糊掉，文档类的图片画质要保持高一点。</p>\n<p>截图用 85% 最合适。界面保持清晰，文件缩小 90%，图片看着干净。</p>\n<p>存成 BMP 的照片用 80% 到 85% 最合适。照片看着干净，文件只有 BMP 的零头。</p>\n<p>要发给有大小限制的表单时，从 85% 开始逐步往下调。每调一步看一下大小，文件刚好符合要求就停下。</p>\n<h2 id=\"colour-depth\">颜色深度会怎么样？</h2>\n<p>24 位 BMP 转 JPG 很干净，因为 JPG 同样用 24 位颜色。原图里的几百万种颜色，在 JPG 压缩允许的范围内都保留下来了。</p>\n<p>带调色板的 8 位 BMP 也能转。调色板里的颜色变成 JPG 里普通的 RGB 颜色，图片看起来一样。</p>\n<p>1 位黑白 BMP，比如传真扫描件，转成 JPG 后只有黑白像素。图片很简单，文件缩小得非常厉害。</p>\n<p>老式的 1 位和 8 位 BMP 文件都完全支持。转换器读取调色板和像素数据，JPG 会忠实地还原图片。</p>\n<h2 id=\"scanned-bmp-files\">扫描的 BMP 文件为什么压得这么好？</h2>\n<p>扫描的 BMP 文件大多是白纸加黑字。这种简单内容用 JPG 压缩效果极好，因为大面积纯色只需要很少字节。</p>\n<p>一张 10MB 的扫描 BMP，用 85% 画质可以变成 300KB 的 JPG。省了 97%，文字依然完全可读。</p>\n<p>纸纹是唯一抗压缩的东西。带噪点的扫描图比干净的扫描图省得少，不过节省依然很可观。</p>\n<p>扫描 BMP 的存档转成 JPG，能腾出好几个 GB 的存储空间。原来装满一块硬盘的文件夹，转完后一个 U 盘就能装下。</p>\n<h2 id=\"transparency-myth\">BMP 有透明度吗？</h2>\n<p>标准 BMP 文件不支持透明度。每个像素都是纯色，没有存放透明区域的透明通道。</p>\n<p>少数罕见的 32 位 BMP 文件带有透明通道，但大多数软件都忽略它。实际使用中，BMP 图片永远是完全不透明的。</p>\n<p>转成 JPG 在透明度上什么都没丢。JPG 同样不透明，图片看起来和原来的 BMP 一模一样。</p>\n<p>需要透明度就把 BMP 转成 PNG。<a href=\"/zh/zhuanhuan-tupian/\">图片转换器</a>能做到，不过 BMP 很少有值得保留的透明度。</p>\n<h2 id=\"batch-converting\">批量转换一整文件夹的 BMP 扫描件</h2>\n<p>一整文件夹的 BMP 扫描件可以一次批量转换。每个文件独立转换，最后打包进一个 ZIP 里。</p>\n<p>整批用同一个画质设置。扫描件属于同一个存档或同一套文档时，保持一致才专业。</p>\n<p>转换后看一下批量汇总。BMP 扫描件的文件夹常常整体缩小 95%，这个数字很惊人，也证明这番功夫是值得的。</p>\n<p>转换后把 BMP 原件留在归档文件夹里。它们是母版，以后需要别的格式还能再转。</p>\n<h2 id=\"checking-quality\">下载前检查画质</h2>\n<p>点任意卡片上的“对比”，就能并排看到 BMP 和 JPG。拖动分隔线，放大看文字和细节。</p>\n<p>先检查最小的文字，因为它受 JPG 压缩影响最大。85% 画质的扫描文档，印刷文字应该完全可读。</p>\n<p>如果文字看着发软，把画质提高 5 个点再转一次。原 BMP 还留在队列里，不用重新上传。</p>\n<p>批量转换时，抽查三四张有代表性的文件就行，不用每张都看。设置相同，抽查的几张没问题，其余的也不会有问题。</p>\n<h2 id=\"bmp-vs-png-decision\">BMP 转 JPG 还是转 PNG？</h2>\n<p>目标是文件更小时选 JPG。BMP 扫描件转成 JPG 能缩小 90% 以上，转成 PNG 却省得少得多。</p>\n<p>图片要反复编辑时选 PNG。PNG 无损，反复保存也不会退化，JPG 每次保存都会多一点损伤。</p>\n<p>截图和扫描件要发给表单或邮件时选 JPG。文件更小，发送更快，上传也不会碰到大小限制。</p>\n<p>线条图和示意图选 PNG，里面每个像素都必须精确。无损格式保留细线条的效果比 JPG 好。</p>\n<h2 id=\"where-jpg-works\">转出来的 JPG 能用在哪里？</h2>\n<p>转出来的 JPG 在任何软件、任何设备上都能打开。Windows 照片、macOS 预览、WhatsApp、老打印机，处理 JPG 都毫无压力。</p>\n<p>它能上传到任何写明接受 JPG 的表单、网站和平台。政务系统、招聘网站、打印店，全都接受 JPG。</p>\n<p>发邮件附件也没问题。BMP 附件常常大到发不出去，JPG 版却能顺利通过，不会碰到上限。</p>\n<p>它打印出来也很干净。打印机只认 JPG，转出来的 JPG 和同等画质的相机 JPG 印出来一模一样。</p>\n<h2 id=\"common-problems\">常见问题与解决办法</h2>\n<p>BMP 文件转换失败，可能是用了不常见的压缩方式或不支持的颜色深度。先在 Windows 画图里打开它，再另存为标准 BMP。</p>\n<p>文字看着模糊，是画质太低了。把滑块拉到 90%，用原 BMP 再转一次。</p>\n<p>JPG 只比 BMP 小一点点，说明图片可能特别简单或噪点很多。简单的图片没什么可压的，噪点在两种格式里都抗压缩。</p>\n<p>颜色看着不对，BMP 可能用了不常见的调色板。仔细检查一下结果，源文件可疑的话，从新导出的文件重新转换。</p>\n<h2 id=\"bmp-from-old-scanners\">老扫描仪出来的 BMP 文件</h2>\n<p>老扫描仪默认常常存成 BMP，简单文档也能扫出巨大的文件。单页扫描件存成 BMP 可能有 10MB，同样一页存成 JPG 只有 300KB。</p>\n<p>扫描件用 85% 到 90% 画质转成 JPG。文字保持可读，文件缩小 95%，存档只占原来的一小部分磁盘空间。</p>\n<p>整个扫描存档一次转五十张分批进行。每批运行都很顺畅，一批出问题也不会影响其他批次。</p>\n<p>转换后把 BMP 原件留在归档文件夹里。它们是母版，以后需要别的格式还能再转。</p>\n<p>以后扫描前先检查扫描仪设置。把扫描仪改成 JPG 或 PDF，就能省掉转换这一步，文件从一开始就是正确的格式。</p>\n<h2 id=\"bmp-from-legacy-software\">老软件出来的 BMP 文件</h2>\n<p>老 Windows 软件常常只能存成 BMP，因为写这个软件的年代 BMP 就是标准。这些文件在别处使用之前需要转换。</p>\n<p>先从老软件里把图片导出为 BMP，再转成 JPG。不管软件多老，这个两步走的办法对每个文件都管用。</p>\n<p>转换后检查一下图片，老软件有时会生成不常见的 BMP 变体。快速看一眼 JPG，就能确认颜色和内容都保留下来了。</p>\n<p>老软件出来的大批文件，分批转换并留好原件。五十个文件一批只要几分钟，原件安全地留在归档文件夹里。</p>\n<p>把转换设置记下来告诉下一个人。一句话就能防止每次老系统迁移时格式慢慢混杂的老问题。</p>\n<h2 id=\"bmp-screenshots-games\">游戏里的 BMP 截图</h2>\n<p>老游戏把截图存成 BMP 文件，体积巨大。一张 1920×1080 的截图存成 BMP 超过 6MB，同样图片存成 JPG 只有 500KB。</p>\n<p>截图用 85% 画质转成 JPG。游戏画面保持锐利，文件缩小 90%，整个合集只占原来的一小部分磁盘空间。</p>\n<p>截图合集按游戏分批转换。每批用同样的设置，文件夹按游戏名整理。</p>\n<p>最重要的截图留着 BMP 原件。喜欢的瞬间值得一份无损母版，JPG 副本是用来分享的。</p>\n<p>网上分享用 JPG 版，游戏论坛和社交媒体都原生处理 JPG。BMP 上传可能失败，慢速网络下上传也要花太久。</p>\n<h2 id=\"bmp-from-cameras\">数码相机出来的 BMP 文件</h2>\n<p>有些数码相机把图片存成 BMP，老型号和工业相机尤其常见。这些文件很大，转成 JPG 才能正常使用。</p>\n<p>相机 BMP 用 85% 画质转成 JPG。照片看着干净，文件大幅缩小，任何看图软件都能打开。</p>\n<p>以后拍摄前先检查相机设置。把相机改成 JPG，就能省掉转换这一步，文件从一开始就是正确的格式。</p>\n<p>打算编辑的照片，留一份 PNG 副本做母版。无损格式反复编辑也不会坏，JPG 每次保存都会多一点损伤。</p>\n<p>转好的 JPG 按日期和事件分文件夹存放。2026-11-家庭旅行这样的文件夹名，几年后还很好找，叫 DCIM 的文件夹就不行了。</p>\n<h2 id=\"archiving-converted-jpgs-bmp\">归档转好的 JPG</h2>\n<p>转好的 JPG 和其他存档一样值得认真对待。按日期和用途分文件夹存放，两年前的文字以后还能找到。</p>\n<p>原 BMP 放在单独的归档文件夹里。它们是母版，分开放能防止两套文件搞混。</p>\n<p>转好的文件按用途命名，别按日期命名。invoice-2024-03.jpg 这样的名字，几年后还有用，scan001.jpg 就不行了。</p>\n<p>存档备份两处。本地硬盘加一份云备份，能防硬件损坏、被盗和误删。</p>\n<p>每隔一两年检查一次存档。不再重要的旧扫描件和截图可以删掉，给真正重要的文件腾出空间。</p>\n<p>准备好把 BMP 文件变小了吗？打开 <a href=\"/zh/bmp-zhuan-jpg/\">BMP 转 JPG 工具</a>，把文件拖进去就行。具体步骤可以看<a href=\"/zh/blog/ruhe-jiang-bmp-zhuan-huan-wei-jpg/\">如何把 BMP 转换成 JPG</a>，文件大小的问题可以看<a href=\"/zh/blog/bmp-vs-jpg-wenjian-daxiao-duibi/\">BMP vs JPG：为什么 BMP 文件这么大</a>。如果要的是 PNG，<a href=\"/zh/zhuanhuan-tupian/\">图片转换器</a>也能把 BMP 转成 PNG。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"BMP 文件为什么比 JPG 大这么多？","answer":"BMP 原样保存每个像素，几乎不压缩，一张 1920×1080 的截图光像素就要 6MB 多。JPG 丢掉人眼几乎注意不到的细节，同一张图压到 500KB。差别在压缩方式，不在图片本身。"},{"question":"BMP 转 JPG 能省多少体积？","answer":"通常能省 90% 以上。一张 10MB 的扫描 BMP，用 85% 画质常常变成 300KB 的 JPG，6MB 的截图变成 500KB。简单的扫描件省得最多，带噪点的图片省得少一些。整批转换后汇总里会显示整个文件夹省下的准确总量。"},{"question":"什么画质设置能让 BMP 截图保持可读？","answer":"85% 是截图的最佳平衡点，界面文字保持清晰，文件缩小 90%。带小字的扫描文档用 85% 到 90%。画质低于 75%，小字就开始变糊，任何带文字的图片都要避免低画质。"},{"question":"转换接受的 BMP 文件最大是多大？","answer":"每个 BMP 文件最大 25MB，大截图和高清扫描件都能覆盖。转换在你的设备上运行，大文件按本地速度处理，不用等上传。"},{"question":"老式的 1 位或 8 位 BMP 文件能转换吗？","answer":"可以。转换器能读取 1 位黑白 BMP、8 位调色板 BMP 和 24 位全彩 BMP。调色板里的颜色会变成 JPG 里普通的 RGB 颜色，图片看起来一样。老 Windows 软件出来的很旧的文件也能干净地转换。"},{"question":"什么时候 BMP 转 JPG 比 BMP 转 PNG 好？","answer":"目标是文件更小的时候。BMP 扫描件转成 JPG 能缩小 90% 以上，转成 PNG 却省得少得多。只有图片要反复编辑时才选 PNG，因为 PNG 无损，JPG 反复保存会叠加损伤。"}];
